python3 -c 'import json,sys,subprocess,os
try:
    d=json.load(sys.stdin)
except Exception:
    sys.exit(0)
p=(d.get("tool_input") or {}).get("file_path") or ""
if p.endswith(".md"):
    b=os.path.join(os.environ.get("CLAUDE_PLUGIN_ROOT",""),"bin","agent-ready-check")
    r=subprocess.run([sys.executable,b,"--changed",p,"--json"],capture_output=True,text=True)
    try:
        data=json.loads(r.stdout or "{}")
    except Exception:
        data={}
    reds=[i["message"] for i in data.get("issues",[]) if i.get("level")=="red"]
    if reds:
        print("agent-ready-check (non-blocking; fix before continuing): "+" | ".join(reds))' || true
